        #         "triggerBy": null,
        #         "triggerPrice": null,
        #         "triggerQuantity": null,
        #         "triggeredAt": null
        #     }
        #
        # fetchOrders
        #     {
        #         "clientId": null,
        #         "createdAt": "2025-07-27T18:05:40.897",
        #         "executedQuantity": "0",
        #         "executedQuoteQuantity": "0",
        #         "expiryReason": null,
        #         "id": "4239996998",
        #         "orderType": "Limit",
        #         "postOnly": false,
        #         "price": "4500",
        #         "quantity": null,
        #         "quoteQuantity": null,
        #         "selfTradePrevention": "RejectTaker",
        #         "side": "Ask",
        #         "status": "Cancelled",
